62			{"ready", func(t *testing.T) *PathModel {
63				pm, _ := newPM(t)
64				pm.ready(pathTarget{Host: host})
65				return pm
66			}},
67			{"done", func(t *testing.T) *PathModel {
68				pm, _ := newPM(t)
