package netdiag

import (
	"fmt"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// pathBarLabel prefixes the target field in the bar.
const pathBarLabel = "Target › "

// pathColumns describes the Path column. Plain text in Cell, colour in Style
// (Rule 122). A silent hop is dim, never red: it is not a failure.
func pathColumns() []datatable.Column[pathStep] {
	hop := datatable.Column[pathStep]{
		Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
		Cell: pathStep.hopCell,
	}
	step := datatable.Column[pathStep]{
		Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
		Cell:  pathStep.stepCell,
		Style: pathStepStyle,
	}
	address := datatable.Column[pathStep]{
		Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
		Cell:  pathStep.addressCell,
		Style: pathAddressStyle,
	}
	rtt := datatable.Column[pathStep]{
		Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
		Cell:  pathStep.rttCell,
		Style: pathRTTStyle,
	}
	return []datatable.Column[pathStep]{hop, step, address, rtt}
}

func pathStepStyle(s pathStep) lipgloss.Style {
	if s.Kind == stepNoResponse {
		return theme.DimStyle
	}
	if s.Kind != stepHop {
		return lipgloss.Style{}
	}
	switch s.Hop.Kind {
	case nettrace.HopSilent, nettrace.HopUnresolved:
		return theme.DimStyle
	case nettrace.HopError:
		return theme.SeverityTextStyle("MEDIUM")
	}
	return lipgloss.Style{}
}

func pathAddressStyle(s pathStep) lipgloss.Style {
	switch s.Kind {
	case stepTrace, stepEngine:
		return theme.DimStyle
	case stepNetwork:
		if s.Container.dimNetwork() {
			return theme.DimStyle
		}
	case stepHop:
		if !s.Hop.Addr.IsValid() {
			return theme.DimStyle
		}
	case stepInterface, stepGateway:
		if c := s.addressCell(); c == routeUndetermined || c == gatewayDirect || c == gatewayNone {
			return theme.DimStyle
		}
	}
	return lipgloss.Style{}
}

func pathRTTStyle(s pathStep) lipgloss.Style {
	if s.Kind == stepNoResponse || (s.Kind == stepHop && s.Hop.RTT <= 0) {
		return theme.DimStyle
	}
	return lipgloss.Style{}
}

// view renders the table; the body is never replaced (Rule 139). The open
// selector is drawn over it.
func (pm *PathModel) view() string {
	if pm.pickerOpen() {
		return pm.viewWithPicker(pm.table.View())
	}
	return pm.table.View()
}

// barView is the target field in its frame, two lines in every state.
func (pm *PathModel) barView(width int) string {
	return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
}

// statusLine is derived on every frame (Rule 128).
func (pm *PathModel) statusLine() components.Status {
	if pm.errText != "" {
		return components.Status{Text: pm.errText, Level: components.LevelError}
	}
	if pm.pickerOpen() {
		return pm.pickerStatus()
	}
	if pm.state != pathRunning {
		if a := pm.launchable(); !a.Enabled() {
			// The platform cannot trace: say so up front, derived every frame.
			return components.Status{Text: a.Reason, Level: components.LevelWarning}
		}
		return components.Status{}
	}
	host := pm.target.Host
	n := pm.hopCount()
	if !pm.addr.IsValid() && n == 0 {
		return components.Status{Text: "Resolving " + host + "...", Activity: true}
	}
	where := host
	if pm.addr.IsValid() && pm.addr.String() != host {
		where += " (" + pm.addr.String() + ")"
	}
	noun := "hops"
	if n == 1 {
		noun = "hop"
	}
	return components.Status{
		Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
		Activity: true,
	}
}

// headerInfo lists the target and, once a run ended, how it ended.
func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
	var out []shortcut.HeaderInfo
	if !pm.source.isHost() {
		out = append(out, shortcut.HeaderInfo{Key: "Source", Value: pm.source.Name, Style: theme.HeaderValueStyle})
	}
	if pm.target.Host != "" {
		value := pm.target.String()
		if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
			value += " (" + pm.addr.String() + ")"
		}
		out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
	}
	if pm.result != nil {
		out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
	}
	return out
}

// shortcuts: the running mode replaces the list, the other states grey out
// (Rule 130).
func (pm *PathModel) shortcuts() shortcut.Shortcuts {
	if pm.pickerOpen() { // a mode: the list is replaced
		return shortcut.Shortcuts{
			{Key: "enter", Description: "Trace from it"},
			{Key: "esc", Description: "Close"},
		}
	}
	off := !pm.launchable().Enabled()
	source := shortcut.Shortcut{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()}
	switch pm.state {
	case pathRunning:
		return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
	case pathDone, pathReady:
		return shortcut.Shortcuts{
			{Key: "tab", Description: "Switch tab"},
			{Key: "enter", Description: "Trace again", Disabled: off},
			source,
			{Key: "esc", Description: "Edit the target"},
			{Key: "?", Description: "Help"},
		}
	}
	return shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
		{Key: "enter", Description: "Trace the path", Disabled: off},
		source,
	}
}

package netdiag

import (
	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// traceTitleMargin is what the frame takes from the title line: corners,
	// rules and the spaces around the title.
	traceTitleMargin = 8

	// traceTitleTrail is what follows "Network" in the sub-level's title.
	traceTitleTrail = " › Path › "
)

// startFromForm starts a trace on tg from the Diagnostics form. It reuses this
// model rather than a second instance: the previous run is replaced, then the
// run is launched. It returns nil, and starts nothing, when the platform cannot
// trace. The Cmd does the I/O only (Rule 110).
func (pm *PathModel) startFromForm(tg pathTarget) tea.Cmd {
	if !pm.launchable().Enabled() {
		return nil
	}
	pm.ready(tg)
	_, cmd := pm.launch(tg)
	return cmd
}

// ready puts the model in its ready state on tg: nothing is sent, the source is
// this machine and the previous run is forgotten.
func (pm *PathModel) ready(tg pathTarget) {
	pm.state = pathReady
	pm.target = tg
	pm.source = hostSource()
	pm.picker = nil
	pm.clearRun()
	pm.footer.Clear()
	pm.input.SetValue(tg.Host)
	pm.input.Blur()
}

// openTrace enters the sub-level on tg, remembering where esc leads back to.
func (m *Model) openTrace(origin ViewState, tg pathTarget) {
	m.traceOrigin = origin
	m.state = StateTrace
	m.activeTab = tabDiagnostics
	m.pathModel.ready(tg)
}

// inTrace reports whether the trace sub-level is on screen.
func (m *Model) inTrace() bool {
	return m.activeTab == tabDiagnostics && m.state == StateTrace
}

// handleKeyTrace is the keyboard of the sub-level. It is explicit: esc, the
// table's navigation, ctrl+o and enter act (the last two only while no trace
// runs: the running mode lists esc alone), and every other key is dropped
// rather than handed to the Path model.
func (m *Model) handleKeyTrace(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	key := msg.String()
	switch {
	case key == "esc":
		return m.escFromTrace()
	case isPathNavKey(key):
		return m, m.pathModel.table.Update(msg)
	case key == pathSourceKey && !m.pathModel.running():
		_, cmd := m.pathModel.openPicker()
		return m, cmd
	case key == "enter" && !m.pathModel.running():
		_, cmd := m.pathModel.launch(m.pathModel.target)
		return m, cmd
	}
	return m, nil
}

// escFromTrace cancels a running trace; otherwise it goes back to where the
// sub-level was opened from, with its fields, focus, filter and results kept.
func (m *Model) escFromTrace() (*Model, tea.Cmd) {
	if m.pathModel.running() {
		_, cmd := m.pathModel.cancelRun()
		return m, cmd
	}
	m.state = m.traceOrigin
	if m.traceOrigin == StateInput {
		m.restoreFormFocus()
	}
	return m, nil
}

// restoreFormFocus puts the cursor back where focusedField says it is, so only
// that field blinks.
func (m *Model) restoreFormFocus() {
	for _, in := range []*textinput.Model{&m.targetInput, &m.portInput, &m.dnsServerInput} {
		in.Blur()
	}
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

// traceTitle is "Network › Path › host", the host cut with an ellipsis so the
// line never outgrows the frame.
func (m *Model) traceTitle(base string) string {
	host := m.pathModel.target.Host
	if m.width > 0 {
		avail := m.width - traceTitleMargin - ansi.StringWidth(base+traceTitleTrail)
		host = ansi.Truncate(host, max(avail, 1), "…")
	}
	return base + titleTrailStyle().Render(traceTitleTrail+host)
}

// traceShortcuts is the only constructor of the sub-level's shortcuts. The
// selector and a running trace are modes and replace the list; ready and done
// share one key set, with greyed entries (Rule 130).
func (m *Model) traceShortcuts() shortcut.Shortcuts {
	pm := m.pathModel
	if pm.pickerOpen() {
		return shortcut.Shortcuts{
			{Key: "enter", Description: "Trace from it"},
			{Key: "esc", Description: "Close"},
		}
	}
	if pm.running() {
		return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
	}
	enter := "Trace the path"
	if pm.state == pathDone {
		enter = "Trace again"
	}
	esc := "Back to the results"
	if m.traceOrigin == StateInput {
		esc = "Back to the form"
	}
	return shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
		{Key: "enter", Description: enter, Disabled: !pm.launchable().Enabled()},
		{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()},
		{Key: "esc", Description: esc},
		{Key: "?", Description: "Help"},
	}
}

// titleTrailStyle colors what trails "Network" in the title.
func titleTrailStyle() lipgloss.Style {
	return lipgloss.NewStyle().Foreground(theme.ColorPrimary).Background(theme.ColorBackground)
}

package netdiag

import (
	"log"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

const (
	// reasonNotARouteRow is the refusal of H off the Local route row. The header
	// greys the key out and the handler says the same thing at the footer.
	reasonNotARouteRow = "Select the Local route row to trace its path"

	// reasonPathBusy is the refusal when a trace is already running.
	reasonPathBusy = "A path trace is already running — esc cancels it"
)

// pathFromRoute is the one answer to "can H open the trace for this row", read
// by the header and by the handler (Rule 130). The reasons come in this order:
// the platform, the row, then the target the trace would be asked about.
func (m *Model) pathFromRoute() shortcut.Availability {
	if a := m.traceable(); !a.Enabled() {
		return a
	}
	if c, ok := m.checksTable.Selected(); !ok || c.ID != netcheck.CheckRoute {
		return shortcut.Unavailable(reasonNotARouteRow)
	}
	if _, err := parsePathTarget(m.targetInput.Value()); err != nil {
		return shortcut.Unavailable(capitalize(err.Error()))
	}
	return shortcut.Availability{}
}

// tracePathFromRoute opens the trace sub-level on the results' target, in its
// ready state: nothing is resolved or sent until the user presses enter there.
func (m *Model) tracePathFromRoute() (*Model, tea.Cmd) {
	if a := m.pathFromRoute(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	if m.pathModel.running() {
		return m, m.footer.Warn(reasonPathBusy)
	}
	tg, err := m.buildTarget()
	if err != nil {
		log.Printf("ERROR [netdiag] target invalid on path hand-off: %v", err)
		return m, m.footer.Error("Cannot trace — the target is no longer valid")
	}
	m.openTrace(StateResults, pathTarget{Host: tg.Host})
	return m, nil
}

// prefill puts host in the field and returns the tab to editing, dropping the
// outcome of an earlier trace.
func (pm *PathModel) prefill(host string) tea.Cmd {
	pm.state = pathEditing
	pm.target = pathTarget{}
	pm.source = hostSource()
	pm.picker = nil
	pm.clearRun()
	pm.input.SetValue(host)
	pm.input.CursorEnd()
	return pm.input.Focus()
}

package netdiag

import (
	"strings"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/overlay"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

const (
	// textReadingSources is the footer state while the selector's list loads.
	textReadingSources = "Reading running containers..."

	// pickerTopRow is the body row the selector starts on: the table's header
	// row stays visible above it.
	pickerTopRow = 1
)

// sourceChoosable is the one answer to "can the selector open here", read by
// the header and by the handler (Rule 130).
func (pm *PathModel) sourceChoosable() shortcut.Availability {
	if pm.running() {
		return shortcut.Unavailable(reasonPathBusy)
	}
	return pm.launchable()
}

// openPicker opens the selector and asks for its list. The engine is read by
// the Cmd only (Rule 110); the answer comes back as a pathSourcesMsg.
func (pm *PathModel) openPicker() (*PathModel, tea.Cmd) {
	if a := pm.sourceChoosable(); !a.Enabled() {
		return pm, pm.footer.Warn(a.Reason)
	}
	pm.sourcesGen++
	p := newPathSourcePicker(pm.source)
	pm.picker = &p
	return pm, loadPathSourcesCmd(pm.sourcesGen, pm.resolveTimeout, pm.engine)
}

// closePicker drops the selector, and with it any listing still on its way.
func (pm *PathModel) closePicker() { pm.picker = nil }

// handleSources fills the selector. An answer to an older request, or one that
// arrives after the selector closed, changes nothing.
func (pm *PathModel) handleSources(msg pathSourcesMsg) (*PathModel, tea.Cmd) {
	if pm.picker == nil || msg.gen != pm.sourcesGen {
		return pm, nil
	}
	p := pm.picker.withList(msg.list)
	pm.picker = &p
	return pm, nil
}

// handlePickerKey gives the open selector every key: nothing reaches the field
// or the tab row.
func (pm *PathModel) handlePickerKey(key string) (*PathModel, tea.Cmd) {
	switch key {
	case "enter":
		return pm.chooseSource()
	case "esc":
		pm.picker = nil
	default:
		p := pm.picker.move(key, pickerRows(pm.pickerHeight()))
		pm.picker = &p
	}
	return pm, nil
}

// chooseSource closes the selector on the entry under the cursor. Choosing the
// source in use changes nothing; another one empties the column and keeps the
// target. With a target the model goes back to ready and sends nothing; without
// one (step 3 removes that case) it returns to editing.
func (pm *PathModel) chooseSource() (*PathModel, tea.Cmd) {
	chosen := pm.picker.selected()
	pm.picker = nil
	if chosen.ID == pm.source.ID {
		return pm, nil
	}
	pm.source = chosen
	pm.clearRun()
	if pm.target.Host != "" {
		pm.state = pathReady
		return pm, nil
	}
	pm.state = pathEditing
	return pm, pm.input.Focus()
}

// pickerHeight is the room the selector has: the body below the header row.
func (pm *PathModel) pickerHeight() int { return pm.height - pickerTopRow }

// pickerRows is how many entries fit in height lines, borders excluded.
func pickerRows(height int) int { return max(height-pickerFrameRows, 1) }

// pickerStatus is the footer state while the selector is open: the loading
// dot, then the note that explains a list reduced to this machine (Rule 128).
func (pm *PathModel) pickerStatus() components.Status {
	if pm.picker.loading {
		return components.Status{Text: textReadingSources, Activity: true}
	}
	return components.Status{Text: pm.picker.note}
}

// viewWithPicker draws the selector over the table, which stays the body
// (Rules 112, 139).
func (pm *PathModel) viewWithPicker(body string) string {
	width := pm.table.RenderedWidth()
	box := pm.picker.render(width, pm.pickerHeight())
	x := max((width-pickerBoxWidth(width))/2, 0)
	return strings.Join(overlay.Compose(strings.Split(body, "\n"), box, x, pickerTopRow, width), "\n")
}

