50	func pmHopTTLs(pm *PathModel) []int {
51		var out []int
52		for _, s := range pm.table.Items() {
53			if s.Kind == stepHop {
54				out = append(out, s.Hop.TTL)
55			}
56		}
57		return out
58	}
59	
60	func pmFooter(pm *PathModel, width int) string {
61		return ansi.Strip(pm.footer.View(width, pm.statusLine()))
62	}
63	
64	func headerValue(pm *PathModel, key string) (string, bool) {
65		for _, h := range pm.headerInfo() {
66			if h.Key == key {
67				return h.Value, true
68			}
69		}
70		return "", false
71	}
72	
73	func hopOf(ttl int, kind nettrace.HopKind) nettrace.Hop {
74		return nettrace.Hop{TTL: ttl, Kind: kind, Addr: netip.MustParseAddr("10.0.0.1")}
75	}
