// isTraceReady is the "ready" state of the plan (target known, nothing sent):
// neither running, nor finished, nor the tab's editing state.
func isTraceReady(pm *PathModel) bool {
	return !pm.running() && pm.state != pathDone && pm.state != pathEditing
}

